package ru.bluenet.vpn;
import android.content.*;
import android.os.*;
import android.text.InputFilter;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Shared full-screen / overlay chat. Sending always requires an explicit tap. */
final class ChatPanel extends LinearLayout {
 private final Spinner recipient;private final TextView history;private final EditText input;private final Handler handler=new Handler(Looper.getMainLooper());private final ArrayList<String> ips=new ArrayList<>();private String roster="",last="";private final ScrollView scroll;private final boolean compact;private final Button sendButton;private final TextView help,recipientLabel;private final Button quickButton,inlineQuick;private boolean followNext;private String cardIpNotice="";private GameCardUi.Owner cardOwner;
 private final Runnable poll=new Runnable(){public void run(){refresh();handler.postDelayed(this,1000);}};
 ChatPanel(Context c){this(c,false);}
 ChatPanel(Context c,boolean small){super(c);cardOwner=new GameCardUi.Owner(c);compact=small;setOrientation(VERTICAL);setPadding(EasyUi.dp(c,4),EasyUi.dp(c,2),EasyUi.dp(c,4),EasyUi.dp(c,2));setBackgroundColor(EasyUi.bg(c));
  help=EasyUi.text(c,EasyUi.t(c,"Чат Android ↔ Android. Windows Radmin не поддерживается.","Android ↔ Android chat. Windows Radmin is not supported."),12);help.setContentDescription(help.getText());help.setEllipsize(android.text.TextUtils.TruncateAt.END);help.setOnClickListener(v->Toast.makeText(c,help.getText(),Toast.LENGTH_LONG).show());addView(help);
  recipientLabel=EasyUi.text(c,EasyUi.t(c,"Кому","To"),12);addView(recipientLabel);recipient=new Spinner(c);recipient.setMinimumHeight(EasyUi.dp(c,48));recipient.setContentDescription(EasyUi.t(c,"Получатель сообщения","Message recipient"));recipient.setEnabled(false);addView(recipient,new LayoutParams(-1,-2));
  scroll=new ScrollView(c);scroll.setFillViewport(true);history=EasyUi.text(c,"",14);history.setTextIsSelectable(true);scroll.addView(history);LayoutParams messages=small?new LayoutParams(-1,EasyUi.dp(c,120)):new LayoutParams(-1,0,1);messages.topMargin=EasyUi.dp(c,8);messages.bottomMargin=EasyUi.dp(c,8);addView(scroll,messages);
  quickButton=EasyUi.secondary(c,EasyUi.t(c,"Быстрые фразы","Quick phrases"),()->showPhrases());LayoutParams quickParams=new LayoutParams(-1,-2);quickParams.bottomMargin=EasyUi.dp(c,8);quickButton.setContentDescription(EasyUi.t(c,"Быстрые фразы","Quick phrases"));addView(quickButton,quickParams);
  LinearLayout composer=new LinearLayout(c);composer.setGravity(android.view.Gravity.BOTTOM);inlineQuick=EasyUi.icon(c,"+",EasyUi.t(c,"Быстрые фразы","Quick phrases"),()->showPhrases());inlineQuick.setVisibility(GONE);LayoutParams inlineParams=new LayoutParams(EasyUi.dp(c,48),EasyUi.dp(c,48));inlineParams.rightMargin=EasyUi.dp(c,8);composer.addView(inlineQuick,inlineParams);
  input=new EditText(c);input.setTextColor(EasyUi.ink(c));input.setTextSize(15);input.setHintTextColor(EasyUi.dark(c)?0xffaabbcc:0xff63738a);input.setHint(EasyUi.t(c,"Сообщение…","Message…"));input.setContentDescription(EasyUi.t(c,"Сообщение (до 400 символов)","Message (up to 400 characters)"));input.setPadding(EasyUi.dp(c,12),EasyUi.dp(c,10),EasyUi.dp(c,12),EasyUi.dp(c,10));input.setBackground(EasyUi.shape(c,EasyUi.dark(c)?0xff223651:0xffe8f0ff,14));input.setMinimumHeight(EasyUi.dp(c,48));input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(400)});input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setMaxLines(3);input.setSaveEnabled(false);input.setImportantForAutofill(IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEND);input.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEND){send(input.getText().toString());return true;}return false;});LayoutParams inputParams=new LayoutParams(0,-2,1);inputParams.rightMargin=EasyUi.dp(c,8);composer.addView(input,inputParams);
  sendButton=EasyUi.icon(c,"↑",EasyUi.t(c,"Отправить","Send"),()->send(input.getText().toString()));sendButton.setEnabled(false);sendButton.setAlpha(.45f);composer.addView(sendButton,new LayoutParams(EasyUi.dp(c,48),EasyUi.dp(c,48)));addView(composer,new LayoutParams(-1,-2));
  input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){updateSend();}public void afterTextChanged(android.text.Editable e){}});

 }
 private void showPhrases(){Context c=getContext();PopupMenu menu=new PopupMenu(c,input);String[] phrases={EasyUi.t(c,"Я готов, запускай игру","Ready, start the game"),EasyUi.t(c,"Зайди в игру","Join the game"),EasyUi.t(c,"Переподключаюсь, подожди","Reconnecting, please wait")};for(String phrase:phrases)menu.getMenu().add(phrase);menu.getMenu().add(0,101,0,EasyUi.t(c,"Поделиться игровым миром…","Share game world…"));menu.getMenu().add(0,102,0,EasyUi.t(c,"Карточки игровых миров…","Game world cards…"));menu.setOnMenuItemClickListener(item->{int pos=recipient.getSelectedItemPosition();String peer=pos>=0&&pos<ips.size()?ips.get(pos):"";if(item.getItemId()==101)GameCardUi.compose(cardOwner,peer,null,()->{followNext=true;refresh();});else if(item.getItemId()==102)GameCardUi.list(cardOwner,peer,()->refresh());else{input.setText(item.getTitle());input.setSelection(input.length());}return true;});menu.show();}
 private void updateSend(){boolean allowed=!ips.isEmpty()&&!input.getText().toString().trim().isEmpty();sendButton.setEnabled(allowed);sendButton.setAlpha(allowed?1f:.45f);}
 private void send(String text){int index=recipient.getSelectedItemPosition();if(index<0||index>=ips.size()){EasyUi.toast(getContext(),"Нет подключённых получателей","No connected recipients");return;}try{BlueVpnService.chat(ips.get(index),text);followNext=true;input.setText("");refresh();}catch(Exception e){EasyUi.toast(getContext(),"Не отправлено. Подключитесь к сети и проверьте сообщение (до 400 символов).","Not sent. Connect to a network and check the message (up to 400 characters).");}}
 @Override protected void onMeasure(int width,int height){boolean shortWindow=!compact&&android.view.View.MeasureSpec.getMode(height)!=android.view.View.MeasureSpec.UNSPECIFIED&&android.view.View.MeasureSpec.getSize(height)<EasyUi.dp(getContext(),360);help.setVisibility(shortWindow?GONE:VISIBLE);recipientLabel.setVisibility(shortWindow||compact?GONE:VISIBLE);quickButton.setVisibility(shortWindow?GONE:VISIBLE);inlineQuick.setVisibility(shortWindow?VISIBLE:GONE);int lines=shortWindow&&android.view.View.MeasureSpec.getSize(height)<EasyUi.dp(getContext(),280)?1:3;if(input.getMaxLines()!=lines)input.setMaxLines(lines);int helpLines=getResources().getConfiguration().fontScale>1.3f?1:2;if(help.getMaxLines()!=helpLines)help.setMaxLines(helpLines);super.onMeasure(width,height);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();if(cardOwner.closed())cardOwner=new GameCardUi.Owner(getContext());handler.post(poll);}
 @Override protected void onDetachedFromWindow(){cardOwner.close();handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
 private void refresh(){Context c=getContext();if(!cardOwner.allowed())cardOwner.close();boolean connected=false;try{connected=new JSONObject(NativeBridge.status()).optString("phase").equals("connected");}catch(Exception ignored){}JSONObject peers=ChatEngine.peers();ArrayList<String> names=new ArrayList<>(),next=new ArrayList<>();if(peers!=null){Iterator<String> it=peers.keys();while(it.hasNext()&&next.size()<200){JSONObject view=peers.optJSONObject(it.next()),p=view==null?null:view.optJSONObject("peer");if(p!=null&&view.optString("status").equals("Connected")){String ip=p.optString("vip");if(ChatEngine.member(ip)!=null){next.add(ip);names.add(p.optString("name",ip)+" · "+ip);}}}}
  String signature=connected+"/"+names;if(!signature.equals(roster)){String selected=recipient.getSelectedItemPosition()>=0&&recipient.getSelectedItemPosition()<ips.size()?ips.get(recipient.getSelectedItemPosition()):"";roster=signature;ips.clear();ips.addAll(next);if(names.isEmpty())names.add(EasyUi.t(c,connected?"Нет подключённых устройств":"Сначала подключитесь к сети",connected?"No connected devices":"Connect to a network first"));ArrayAdapter<String> adapter=new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,names){@Override public android.view.View getView(int position,android.view.View recycled,android.view.ViewGroup parent){TextView label=EasyUi.text(c,getItem(position),14);label.setSingleLine();label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setPadding(EasyUi.dp(c,10),EasyUi.dp(c,12),EasyUi.dp(c,28),EasyUi.dp(c,12));return label;}};recipient.setAdapter(adapter);int index=ips.indexOf(selected);if(index>=0)recipient.setSelection(index);recipient.setEnabled(!ips.isEmpty());recipient.setAlpha(ips.isEmpty()?.65f:1f);}
  updateSend();ChatStore store=ChatStore.get(c);JSONArray rows=store.rows();String currentCardIp=GameCardUi.ownIp();if(!currentCardIp.isEmpty()&&!currentCardIp.equals(cardIpNotice)){for(int cardIndex=0;cardIndex<rows.length();cardIndex++){JSONObject cardRow=rows.optJSONObject(cardIndex);GameCard oldCard=cardRow==null?null:GameCard.parse(cardRow.optString("text"));if(oldCard!=null&&cardRow.optBoolean("out")&&!oldCard.ip.equals(currentCardIp)){cardIpNotice=currentCardIp;EasyUi.toast(c,"Ваш IP изменился. Откройте карточки игровых миров и отправьте обновление нужному получателю.","Your IP changed. Open Game world cards and send an update to the intended recipient.");break;}}}StringBuilder text=new StringBuilder();java.text.DateFormat time=android.text.format.DateFormat.getTimeFormat(c);for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;String state=x.optString("state");text.append(time.format(new Date(x.optLong("time")))).append(" · ").append(x.optBoolean("out")?EasyUi.t(c,"Вы → ","You → ")+x.optString("name"):x.optString("name")).append("\n").append(GameCardUi.history(c,x)).append("\n");if(x.optBoolean("out"))text.append(EasyUi.t(c,state.equals("delivered")?"Доставлено":state.equals("failed")?"Нет подтверждения доставки":"Ожидание подтверждения",state.equals("delivered")?"Delivered":state.equals("failed")?"Delivery unconfirmed":"Awaiting confirmation")).append("\n");text.append("\n");}
  if(text.length()==0)text.append(ips.isEmpty()?EasyUi.t(c,connected?"Попросите друга войти в ту же сеть. Для чата на обоих телефонах нужна обновлённая «Синяя сеть».":"Откройте вкладку «Сети», подключите VPN и войдите в сеть друга или создайте свою.",connected?"Ask a friend to join the same network. Both phones need an updated Blue Network app for chat.":"Open Networks, connect the VPN and join your friend's network or create your own."):EasyUi.t(c,"Выберите получателя выше, напишите сообщение и нажмите ↑.","Choose a recipient above, type a message and tap ↑."));String rendered=text.toString();if(!last.equals(rendered)){boolean follow=followNext||last.isEmpty()||history.getHeight()-scroll.getHeight()-scroll.getScrollY()<=EasyUi.dp(c,48);int position=scroll.getScrollY();last=rendered;history.setText(rendered);scroll.post(()->{if(follow)scroll.fullScroll(FOCUS_DOWN);else scroll.scrollTo(0,position);});}followNext=false;store.read();
 }
}
